    if (sigintPolicy.press(headless: false) == SigintAction.exitInteractive) {
      final exit = callbacks.onCtrlCExit;
      if (exit != null) {
        return (
          copyWith(ctrlCArmed: false),
          () async {
            exit();
            return null;
