13:/// A buffered line sink over [file]: truncates whatever a previous run
14:/// left (ONE trace per file — each armed run replaces the last trail;
15:/// collect across runs by copying the file between runs), then appends
16:/// lines in batches. Batching keeps the per-mark cost off the hot
17:/// stream path (a sync fsync per SSE chunk would perturb the very
18:/// cadence being measured): lines flush on a [flushInterval] timer,
19:/// when the buffer crosses [_kFlushThresholdBytes], or on
20:/// [flush]/[dispose]. The trade is explicit — up to one interval of
21:/// buffered lines is lost on a hard kill. Diagnostics contract: an IO
22:/// failure degrades to silence, never throws into the caller.
23:final class FileStreamTraceSink implements StreamTraceSink {
24:  /// Truncates [file] for a fresh trace and arms the flush timer.
25:  FileStreamTraceSink(
26:    this._file, {
27:    Duration flushInterval = const Duration(milliseconds: 250),
28:  }) {
29:    try {
30:      _file.writeAsStringSync('', flush: true);
31:    } catch (_) {
32:      // A broken trace path never breaks the host.
33:    }
34:    _timer = Timer.periodic(flushInterval, (_) => flush());
35:  }
36:
37:  /// Buffered lines flush when the buffer crosses this many bytes
38:  /// (bounded memory on a bursty endpoint between timer ticks).
39:  static const int _kFlushThresholdBytes = 64 * 1024;
40:
41:  final File _file;
42:  late final Timer _timer;
43:  final StringBuffer _pending = StringBuffer();
44:
45:  @override
46:  void writeLine(String line) {
47:    _pending
48:      ..write(DateTime.now().toIso8601String())
49:      ..write(' ')
50:      ..write(line)
51:      ..write('\n');
52:    if (_pending.length >= _kFlushThresholdBytes) flush();
53:  }
54:
55:  /// Writes any buffered lines now (also driven by the flush timer).
56:  void flush() {
57:    if (_pending.isEmpty) return;
58:    final batch = _pending.toString();
59:    _pending.clear();
60:    try {
61:      _file.writeAsStringSync(batch, mode: FileMode.append, flush: true);
62:    } catch (_) {
63:      // A broken trace path never breaks the host.
64:    }
65:  }
66:
67:  /// Cancels the timer and flushes the tail. The CLI never calls this
68:  /// (the trace is process-lifetime); tests and embedders may.
69:  void dispose() {
70:    _timer.cancel();
71:    flush();
72:  }
73:}
