/// finished blocks, the dead in-flight block dropped (issue #1132 r2).
Context _resumeAfterPartial(
  Model model,
  AssistantMessage snapshot,
  int keptBlocks,
  StopReason reason,
  int attempt,
  int maxAttempts,
  Context context,
  _ResumeState resume,
  CancelToken? cancelToken,
) {
  resume.absorb(snapshot, keptBlocks);
  transientRetryNotice?.call(
