+      expect(nested.readAsStringSync(), contains('net'));
+    });
+
+    test('flush on a broken path degrades to silence, never throws', () {
+      final sink = FileStreamTraceSink(file);
+      StreamTrace.start(sink);
+      StreamTrace.mark(StreamTraceMark.net, '+1B');
