+  StreamTrace._(this._sink) : _sw = Stopwatch()..start();
+
+  final StreamTraceSink _sink;
+  final Stopwatch _sw;
+  var _lastMs = 0;
+  var _seq = 0;
+  var _closed = false;
+
+  static StreamTrace? _active;
+
+  /// The currently active trace, if a host started one.
